pub fn table(lang: &str) -> &'static [(&'static str, &'static str)] {
    match lang {
        "en" => EN,
        "de" => DE,
        "el" => EL,
        "es" => ES,
        "fr" => FR,
        "it" => IT,
        "zh" => ZH,
        _ => EN,
    }
}
